#!/usr/bin/env node
/**
 * `npm run db:bundle` — build a single SQL script from the migration history.
 *
 * The authoritative history stays `supabase/migrations/` (one file per change,
 * applied by the Supabase CLI). This script only *derives* a concatenated copy
 * for the deployment path that needs neither the CLI nor a database password:
 * a brand-new project set up entirely from the Supabase Dashboard SQL Editor.
 *
 * The generated file IS committed (`supabase/bundle/campus-plus-schema.sql`) so
 * the operator can open it straight from GitHub — there is no build step to run
 * before deploying. `tests/bundle.test.js` fails if it ever goes stale, which is
 * what keeps a tracked generated file honest.
 *
 * Usage:
 *   npm run db:bundle            # regenerate + write the bundle
 *   npm run db:bundle -- --check # exit 1 if the committed bundle is stale
 */

import { mkdir, readdir, readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
export const migrationsDir = path.join(root, 'supabase', 'migrations');
export const outDir = path.join(root, 'supabase', 'bundle');
export const outFile = path.join(outDir, 'campus-plus-schema.sql');

/** Build the bundle content in memory. Used by the CLI *and* by the test. */
export async function buildBundle() {
  const files = (await readdir(migrationsDir)).filter((name) => name.endsWith('.sql')).sort();
  if (files.length === 0) throw new Error('No migrations found in supabase/migrations.');

  const parts = [];
  const contents = [];

  for (const [index, file] of files.entries()) {
    const sql = await readFile(path.join(migrationsDir, file), 'utf8');
    contents.push({ file, sql });
    parts.push(
      `\n-- ${'='.repeat(74)}\n` +
        `-- FILE ${String(index + 1).padStart(2, '0')}/${files.length}  ${file}\n` +
        `-- ${'='.repeat(74)}\n\n${sql.trimEnd()}\n`,
    );
  }

  const header = `-- Campus+ — complete schema, permissions, functions and reference data.
--
-- GENERATED by \`npm run db:bundle\` from supabase/migrations/. Do not edit by
-- hand: CI (\`npm test\`) fails if this file is out of date with the migrations.
--
-- How to deploy with this file (Dashboard only — no CLI, no database password)
--   1. Supabase dashboard → SQL Editor → New query.
--   2. Paste this entire file and press Run. It is written as one one-shot
--      script; run it once on an empty project.
--   3. Confirm the reference data loaded:
--        select count(*) from public.roles;             -- 4
--        select count(*) from public.permissions;       -- 56
--        select key, value from public.platform_settings where key = 'allowed_email_domains';
--   4. Sign in with an @pccoepune.org address, then grant the first Super Admin
--      (see docs/DEPLOYMENT.md §7).
--
-- Prefer the CLI when you have it (it tracks which migrations are applied):
--   supabase link --project-ref <ref> && supabase db push
--
-- What it creates, in order
--   extensions and enums → identity, roles and permissions → blocks →
--   communities → social → moderation → messaging → marketplace → campus →
--   Random → platform → auth hooks → reference data (college, roles,
--   permissions, categories, feature flags, platform settings) → realtime
--   policies and grants → column privileges → staff actions → marketplace
--   hardening → function grants → staff visibility → chat inbox → messaging
--   live read model → transactional backup outbox / worker state (027) →
--   admin-authorized backup processing with durable run leases (028).
--
-- Safety
--   Every statement is idempotent or new-object only, so a re-run on a project
--   that already has the schema is refused by Postgres rather than half-applied.
--   Take a database backup from the dashboard before the first run.
--
-- Contents (${files.length} files):
${contents.map(({ file, sql }, index) => `--   ${String(index + 1).padStart(2, '0')}  ${file}  (${sql.split('\n').length} lines)`).join('\n')}
`;

  return {
    content: `${header}${parts.join('')}${verificationFooter()}`,
    files: contents.map((entry) => entry.file),
  };
}


/**
 * Appended after the migrations.
 *
 * The SQL Editor answers a successful script with "Success. No rows returned",
 * which hides whether the schema, reference data and auth triggers all landed.
 * This footer reports that as a result set, so a deployment is either visibly
 * complete or visibly incomplete.
 *
 * It deliberately uses only SELECTs and `raise warning`: an `exception` in a
 * multi-statement script would roll the whole deployment back.
 */
function verificationFooter() {
  return `
-- ${'='.repeat(74)}
-- VERIFICATION — reports whether the install is complete (no changes made)
-- ${'='.repeat(74)}

do $$
declare
  v_auth_triggers integer;
  v_rls integer;
begin
  select count(*) into v_auth_triggers
    from pg_trigger
   where tgname in ('on_auth_user_created', 'enforce_institutional_domain_trigger')
     and not tgisinternal;

  select count(*) into v_rls
    from pg_class c
    join pg_namespace n on n.oid = c.relnamespace
   where n.nspname = 'public' and c.relkind = 'r' and c.relrowsecurity;

  if v_auth_triggers < 2 then
    raise warning 'Campus+ install incomplete: only % of 2 auth.users triggers exist. Sign-in cannot provision accounts until both are created — re-run the section headed "auth hooks" (file 12) from this script.', v_auth_triggers;
  end if;
  if v_rls < 30 then
    raise warning 'Campus+ install incomplete: only % tables in schema public have row level security. Re-run the migration files in order.', v_rls;
  end if;
end $$;

select
  (select count(*) from public.roles)                 as roles,
  (select count(*) from public.permissions)           as permissions,
  (select count(*) from public.role_permissions)      as role_permissions,
  (select count(*) from public.colleges)              as colleges,
  (select count(*) from public.marketplace_categories) as categories,
  (select count(*) from public.feature_flags)         as feature_flags,
  (select count(*) from public.platform_settings)     as platform_settings,
  (select count(*) from pg_class c
     join pg_namespace n on n.oid = c.relnamespace
    where n.nspname = 'public' and c.relkind = 'r' and c.relrowsecurity) as tables_with_rls,
  (select count(*) from pg_trigger
    where tgname in ('on_auth_user_created', 'enforce_institutional_domain_trigger')
      and not tgisinternal)                           as auth_triggers,
  (select count(*) from pg_proc p
     join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public')                       as public_functions,
  case
    when (select count(*) from public.roles) >= 4
     and (select count(*) from public.permissions) >= 40
     and (select count(*) from public.platform_settings) >= 10
     and (select count(*) from pg_trigger
           where tgname in ('on_auth_user_created', 'enforce_institutional_domain_trigger')
             and not tgisinternal) = 2
    then 'INSTALL OK — next: sign in once, then npm run role:grant -- --email you@pccoepune.org --role super_admin'
    else 'INCOMPLETE — read the warnings above and docs/DEPLOYMENT.md §3'
  end as verdict;
`;
}

const invokedDirectly =
  process.argv[1] && import.meta.url === new URL(`file://${path.resolve(process.argv[1])}`).href;

if (invokedDirectly) {
  const { content, files } = await buildBundle();
  const checkOnly = process.argv.includes('--check');
  const bytes = Buffer.byteLength(content, 'utf8');

  if (checkOnly) {
    let existing = null;
    try {
      existing = await readFile(outFile, 'utf8');
    } catch {
      existing = null;
    }
    if (existing === content) {
      console.log(`${path.relative(root, outFile)} is up to date (${files.length} migrations, ${(bytes / 1024).toFixed(1)} KB).`);
      process.exit(0);
    }
    console.error(
      'supabase/bundle/campus-plus-schema.sql is stale.\n' +
        'Run: npm run db:bundle  (then commit the result)',
    );
    process.exit(1);
  }

  await mkdir(outDir, { recursive: true });
  await writeFile(outFile, content, 'utf8');
  console.log(`Wrote ${path.relative(root, outFile)} — ${files.length} migrations, ${(bytes / 1024).toFixed(1)} KB.`);
  console.log('Open it on GitHub and paste it into the Supabase SQL editor (SQL Editor → New query → Run).');
}
